SET
  @ExtractionStatus_a865a1b0f501 = N'OK'
IF NOT EXISTS (SELECT 1 FROM [${mjSchema}].[Query]
               WHERE [ID] = @ID_a865a1b0f501
                  OR ([CategoryID] = @CategoryID_a865a1b0f501 AND [Name] = @Name_a865a1b0f501))
BEGIN
EXEC [${mjSchema}].spCreateQuery @ID = @ID_a865a1b0f501,
  @Name = @Name_a865a1b0f501,
  @CategoryID = @CategoryID_a865a1b0f501,
