SET
  @ID_0a06044dd790 = '2DC466E2-C634-48EC-AB6E-73A6E7D961DF'
SET
  @Name_0a06044dd790 = N'Sales: Party Lookup Promotable Contacts'
SET
  @CategoryID_0a06044dd790 = '5A1E5000-0000-4000-A000-000000000001'
-- The Sales query category this app ships (metadata/query-categories), found by name with its own
-- ID first: a database can hold more than one category named Sales.
SELECT TOP 1 @CategoryID_0a06044dd790 = [ID] FROM [${mjSchema}].[QueryCategory] WHERE [Name] = N'Sales' ORDER BY CASE WHEN [ID] = @CategoryID_0a06044dd790 THEN 0 ELSE 1 END
SET
  @UserQuestion_0a06044dd790 = N'Which people could be added as sales contacts?'
SET
  @Description_0a06044dd790 = N'Search for the promote dialog: people who do NOT yet have a sales contact row, whose last name, display name or email starts with the term.'
SET
  @SQL_0a06044dd790 = N'-- Promote picker (D-PR3): the EXACT COMPLEMENT of "Sales: Party Lookup Contacts" -- people who do NOT
-- have a SalesContact row, and so cannot yet be named on a deal. The two queries differ in one token,
-- EXISTS against NOT EXISTS, and that is deliberate: a rep who cannot find a person in the contact picker
-- is looking at a person this query returns, and creating a duplicate is the failure this pair exists to
-- prevent (bc-aidp-next-golive#259).
--
-- WHY THIS IS A SEPARATE QUERY RATHER THAN A RELAXED FILTER ON THE OTHER ONE: the contact picker is
-- common''s bizapps-party-field, which has no way to mark a row as unselectable and no BeforeSelect hook.
-- Returning a promotable person THERE would let a rep pick one, setting a deal''s contact FK to a row the
-- server must refuse -- which is what PL1 asserts against. Promotion happens in a sales-owned dialog that
-- reads this query instead, so the picker''s guarantee is untouched.
--
-- Result contract shared by every party lookup query: ID, Name, Detail; parameters Term (required) and
-- Domain (optional, set by the caller when the term looks like part of an email address).
-- Prefix matches on indexed base columns only, TOP 20, no view, no count. sqlLikeBegins escapes %, _ and [ (and drops a trailing %).
SELECT TOP 20
    p.ID,
    p.DisplayName AS Name,
    p.Email       AS Detail
FROM [__mj_BizAppsCommon].Person p
WHERE (
       p.LastName    LIKE {{ Term | sqlLikeBegins }}
    OR p.DisplayName LIKE {{ Term | sqlLikeBegins }}
    OR p.Email       LIKE {{ Term | sqlLikeBegins }}
    {% if Domain %}
    OR p.EmailDomain LIKE {{ Domain | sqlLikeBegins }}
    {% endif %}
)
  AND NOT EXISTS (SELECT 1 FROM [__mj_BizAppsSales].SalesContact sc WHERE sc.ID = p.ID)
ORDER BY p.DisplayName, p.ID
'
SET
  @TechnicalDescription_0a06044dd790 = N'Grain: Person WITHOUT a SalesContact row -- the exact complement of ''Sales: Party Lookup Contacts'', differing only in EXISTS vs NOT EXISTS. Party lookup contract (bc-aidp-next-golive#372): columns ID, Name (Person.DisplayName), Detail (Person.Email); parameters Term (required) and Domain (optional; matched against Person.EmailDomain). Prefix LIKE on indexed base columns (LastName, DisplayName, Email, EmailDomain), TOP 20 ordered by DisplayName, no view and no count. Read by the sales-owned promote dialog, NOT by bizapps-party-field: that control cannot mark a row unselectable, so a promotable person must never reach a deal''s contact picker (PL1).'
SET
  @Status_0a06044dd790 = N'Approved'
SET
  @QualityRank_0a06044dd790 = 8
SET
  @ExecutionCostRank_0a06044dd790 = 1
SET
  @UsesTemplate_0a06044dd790 = 1
SET
  @AuditQueryRuns_0a06044dd790 = 0
SET
  @CacheEnabled_0a06044dd790 = 0
SET
  @Reusable_0a06044dd790 = 0
SET
  @IsMaterialized_0a06044dd790 = 0
SET
  @ApprovedByUserID_0a06044dd790 = 'ECAFCCEC-6A37-EF11-86D4-000D3A4E707E'
SET
  @ApprovedAt_0a06044dd790 = '2026-11-13T16:45:22.049Z'
SET
  @ExtractedSQLHash_0a06044dd790 = N'4c4f01a702cc544ee32006f9abf799daa164b888b9de2207fed2e58b0a7d746a'
SET
  @ExtractionStatus_0a06044dd790 = N'OK'
IF NOT EXISTS (SELECT 1 FROM [${mjSchema}].[Query]
               WHERE [ID] = @ID_0a06044dd790
                  OR ([CategoryID] = @CategoryID_0a06044dd790 AND [Name] = @Name_0a06044dd790))
